import subprocess
import sys
import json

student_answer = """{{ STUDENT_ANSWER }}"""

typescript_program = """// Helper function to check if a variable has explicit type annotation
function checkExplicitType(varName: string, expectedType?: string): boolean {
    const studentCode = """ + json.dumps(student_answer) + """;

    // Regex to match variable declarations with type annotations
    // Matches: let varName: type = ... or const varName: type = ...
    const pattern = new RegExp(
        '\\\\b(let|const|var)\\\\s+' + varName + '\\\\s*:\\\\s*([^=;]+?)\\\\s*[=;]',
        'g'
    );

    const match = pattern.exec(studentCode);

    if (!match) {
        throw new Error('Variable "' + varName + '" must have explicit type annotation');
    }

    if (expectedType) {
        const actualType = match[2].trim();
        if (actualType !== expectedType) {
            throw new Error('Variable "' + varName + '" type annotation must be "' + expectedType + '", got "' + actualType + '"');
        }
    }

    return true;
}

// Helper function to check if a method has explicit return type annotation
function checkExplicitReturnType(methodName: string, expectedReturnType?: string): boolean {
    const studentCode = """ + json.dumps(student_answer) + """;

    // Regex to match method or function declarations with return type annotations
    // Matches: methodName(...) : ReturnType { ... }, function methodName(...) : ReturnType { ... },
    // or arrow functions: const methodName = (...) : ReturnType => { ... }
    const functionPattern = new RegExp(
        '\\\\b(?:function\\\\s+)?' + methodName + '\\\\s*\\\\([^)]*\\\\)\\\\s*:\\\\s*([^\\\\s{=]+)',
        'g'
    );

    const arrowPattern = new RegExp(
        '\\\\b(?:(?:const|let|var)\\\\s+)?' + methodName + '\\\\s*=\\\\s*(?:async\\\\s+)?\\\\([^)]*\\\\)\\\\s*:\\\\s*([^\\\\s=]+)\\\\s*=>',
        'g'
    );

    const match = functionPattern.exec(studentCode) || arrowPattern.exec(studentCode);

    if (!match) {
        throw new Error('Method "' + methodName + '" must have explicit return type annotation');
    }

    if (expectedReturnType) {
        const actualReturnType = match[1].trim();
        if (actualReturnType !== expectedReturnType) {
            throw new Error('Method "' + methodName + '" return type must be "' + expectedReturnType + '", got "' + actualReturnType + '"');
        }
    }

    return true;
}

""" + student_answer + """

