import pymongo
from pymongo import MongoClient
from pymongo.command_cursor import CommandCursor
from bson import ObjectId
import sys
import json
from datetime import datetime
import re

# Get MongoDB connection parameters from template parameters
mongodb_config = {
    'host': '{{ QUESTION.parameters.mongodb_host | default("localhost") }}',
    'port': {{ QUESTION.parameters.mongodb_port | default(27017) }},
    'username': '{{ QUESTION.parameters.mongodb_user | default("") }}',
    'password': '{{ QUESTION.parameters.mongodb_password | default("") }}',
    'authSource': '{{ QUESTION.parameters.mongodb_auth_db | default("admin") }}'
}

database_name = '{{ QUESTION.parameters.mongodb_database | default("test") }}'
collection_name = '{{ QUESTION.parameters.mongodb_collection | default("testcollection") }}'

# Get student's answer as a string (like MySQL does)
student_answer = """{{ STUDENT_ANSWER | e('py') }}""".strip()

SEPARATOR = "#<ab@17943918#@>#"
MAX_LIST_ITEMS = 5        # Limit lengthy array displays for readability
MAX_DISPLAY_DOCS = 10     # Limit number of documents shown per test
MAX_OUTPUT_LENGTH = 7000  # Keep total output below Moodle snipping threshold

# Provide backwards-compatible Collection.count() for PyMongo 4+
try:
    from pymongo.collection import Collection as _Collection
except ImportError:
    _Collection = None

if _Collection is not None and not hasattr(_Collection, 'count'):
    def _legacy_count(self, filter=None, **kwargs):
        if filter is None:
            filter = {}
        return self.count_documents(filter, **kwargs)
    _Collection.count = _legacy_count


def serialize_structure(value, indent=0, max_list_items=MAX_LIST_ITEMS):
    """Recursively serialize MongoDB documents to pretty JSON-like text."""
    indent_str = ' ' * indent
    next_indent = indent + 2
    next_indent_str = ' ' * next_indent

    if isinstance(value, dict):
        if not value:
            return '{}'
        items = []
        keys = sorted(value.keys())
        for key in keys:
            serialized = serialize_structure(value[key], next_indent, max_list_items)
            items.append(f'{next_indent_str}"{key}": {serialized}')
        return '{\n' + ',\n'.join(items) + f'\n{indent_str}' + '}'

    if isinstance(value, list):
        if not value:
            return '[]'
        truncated = len(value) > max_list_items
        elements = value[:max_list_items]
        items = [serialize_structure(item, next_indent, max_list_items) for item in elements]
        rendered = [f'{next_indent_str}{item}' for item in items]
        if truncated:
            remaining = len(value) - max_list_items
            rendered.append(f'{next_indent_str}"... ({remaining} more items)"')
        return '[\n' + ',\n'.join(rendered) + f'\n{indent_str}' + ']'

    if isinstance(value, ObjectId):
        return f'"{str(value)}"'

    if isinstance(value, datetime):
        return f'"{value.isoformat()}"'

    if isinstance(value, str):
        return json.dumps(value)

    return json.dumps(value)


def format_documents(results, max_docs=MAX_DISPLAY_DOCS):
    """Build a readable JSON-formatted string representation of documents."""
    if not results:
        return "[]"

    display_results = results[:max_docs]
    serialized_docs = []
    for idx, doc in enumerate(display_results, start=1):
        serialized = serialize_structure(doc)
        serialized_docs.append(f"{serialized}")

    output = '\n\n'.join(serialized_docs)
    if len(results) > max_docs:
        output += f"\n\n... ({len(results) - max_docs} more documents not shown)"

    if len(output) <= MAX_OUTPUT_LENGTH:
        return output

    truncated = output[:MAX_OUTPUT_LENGTH]
    truncated += f"\n... (output truncated to stay within display limits, {len(output) - MAX_OUTPUT_LENGTH} chars omitted)"
    return truncated

def normalize_student_code(code: str) -> str:
    """
    Normalize Mongo shell–style code so it becomes valid Python:
    - remove trailing semicolons
    - quote unquoted object keys like $group, _id, totalBooks, $sum, $sort, etc.
    - convert true/false/null -> True/False/None
    """
    code = code.strip()

    # Remove trailing semicolons (common in Mongo shell)
    while code.endswith(';'):
        code = code[:-1].rstrip()

    # Quote unquoted keys in object literals:
    # Matches { key: ... } or , key: ...  where key is not quoted
    pattern = re.compile(r'(\{|,)(\s*)([A-Za-z_$][A-Za-z0-9_$]*)\s*:')

    def replacer(match):
        opener = match.group(1)      # { or ,
        spaces = match.group(2)      # whitespace
        key = match.group(3)         # key like $group, _id, totalBooks
        return f'{opener}{spaces}"{key}":'

    code = pattern.sub(replacer, code)

    # Replace Mongo shell boolean/null with Python equivalents
    # Only when they appear as standalone tokens, not inside strings or identifiers
    code = re.sub(r'(?<![A-Za-z0-9_"])\btrue\b(?![A-Za-z0-9_"])', 'True', code)
    code = re.sub(r'(?<![A-Za-z0-9_"])\bfalse\b(?![A-Za-z0-9_"])', 'False', code)
    code = re.sub(r'(?<![A-Za-z0-9_"])\bnull\b(?![A-Za-z0-9_"])', 'None', code)

    return code

def pipeline_has_sort(code: str) -> bool:
    """
    Detect whether the student's aggregation pipeline has a $sort stage.
    Works on shell-style or normalized Python syntax.
    """
    cleaned = re.sub(r'\s+', '', code)
    return '"$sort"' in cleaned or '$sort' in cleaned

def execute_mongodb_query(db, collection, code, normalize=True):
    """Execute MongoDB query string and return results (like MySQL cursor.execute)."""
    namespace = {
        'db': db,
        'collection': collection,
        'ObjectId': ObjectId,
        'datetime': datetime,
        'pymongo': pymongo
    }
    try:
        prepared_code = normalize_student_code(code) if normalize else code
        result = eval(prepared_code, namespace)
        return result
    except Exception as e:
        raise Exception(f"MongoDB query error: {e}")

