    http_base_url = LSP_BASE_URL.replace('wss://', 'https://').replace('ws://', 'http://')
    deploy_url = http_base_url.rstrip('/') + '/api/workspace/create'

    # Prepare deployment payload (filter out hidden stub files)
    deployment_files = []
    for file_entry in student_files:
        path = file_entry.get('path', '')
        # Skip hidden stub files (starting with underscore)
        if path and not re.match(r'^/?_[^/]+\.php$', path):
            deployment_files.append({
                'path': path,
                'content': file_entry.get('content', ''),
                'locked': False,
                'uid': 'null'
            })

    payload = {
        'folderName': workspace_id,
        'files': deployment_files,
        'folders': {},
        'uiState': {'openTabs': [], 'activeFile': ''},
        'timestamp': int(time.time() * 1000)
    }

    # Deploy to server
    try:
        req = urllib.request.Request(
