    except urllib.error.HTTPError as deploy_err:
        # Deployment failed - print detailed error
        error_body = deploy_err.read().decode('utf-8') if deploy_err.fp else ''
        print(f"WARNING: Failed to deploy to Flight server: HTTP {deploy_err.code} - {error_body}")
